package com.bank.settlement;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SettlementSearchDemo {

    private static final Logger log = Logger.getLogger(SettlementSearchDemo.class.getName());

    static {
        // Standard clean logger setup used across the National Bank of India codebase.
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // A globally sorted settlement grid: each row ascending, rows chained together.
        int[][] settledAmounts = {
                {10000, 15000, 22000, 30000},
                {41000, 50000, 58000, 63000},
                {71000, 84000, 90000, 99000}
        };

        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        log.info(() -> "Audit started by " + priya.getHolderName() + " on grid of "
                + (settledAmounts.length * settledAmounts[0].length) + " settled amounts");

        SettlementMatrixSearch search = new SettlementMatrixSearch();

        int presentTarget = 50000;
        boolean found = search.contains(settledAmounts, presentTarget);
        log.info(() -> "Amount " + presentTarget + " present? " + found
                + " (reconciles with " + rajesh.getAccountId() + " transfer)");

        int absentTarget = 55555;
        boolean missing = search.contains(settledAmounts, absentTarget);
        log.info(() -> "Amount " + absentTarget + " present? " + missing);
    }
}

