class SettlementMatrixSearch {

    private static final Logger log = Logger.getLogger(SettlementMatrixSearch.class.getName());

    // Returns true if target exists in a globally sorted matrix. O(log(m*n)) time, O(1) space.
    boolean contains(int[][] matrix, int target) {
        if (matrix == null || matrix.length == 0 || matrix[0].length == 0) {
            return false;
        }
        int rows = matrix.length;
        int cols = matrix[0].length;
        int low = 0;
        int high = rows * cols - 1;

        while (low <= high) {
            int mid = low + (high - low) / 2;   // overflow-safe midpoint
            int row = mid / cols;               // map flattened index back to row
            int col = mid % cols;               // and column
            int value = matrix[row][col];
            log.fine(() -> "probe mid=" + mid + " -> [" + (mid / cols) + "][" + (mid % cols)
                    + "]=" + matrix[mid / cols][mid % cols] + " target=" + target);

            if (value == target) {
                return true;
            } else if (value < target) {
                low = mid + 1;                  // search upper half
            } else {
                high = mid - 1;                 // search lower half
            }
        }
        return false;
    }
}

